<?php
declare(strict_types=1); require_once __DIR__ . '/../config/api.php';
if($_SERVER['REQUEST_METHOD']!=='GET') respond(['success'=>false,'message'=>'Method not allowed'],405);$id=(int)($_GET['id']??0);if($id<=0)respond(['success'=>false,'message'=>'id is required'],422);
$s=$pdo->prepare("SELECT v.id,v.title,v.description,v.openings_count,v.payout_amount,v.payout_period,v.working_hours,v.requirements,v.published_at,v.closing_at,h.id hotel_id,h.name hotel_name,h.description hotel_description,h.address_line,h.city,h.state,h.postcode,h.latitude,h.longitude,c.id category_id,c.name category_name,r.id job_role_id,r.name job_role_name FROM vacancies v INNER JOIN hotels h ON h.id=v.hotel_id INNER JOIN categories c ON c.id=v.category_id INNER JOIN job_roles r ON r.id=v.job_role_id WHERE v.id=? AND v.status='published' AND v.deleted_at IS NULL LIMIT 1");$s->execute([$id]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row)respond(['success'=>false,'message'=>'Job not found'],404);respond(['success'=>true,'data'=>$row]);
